export function ToggleSwitch({ checked, onChange }: { checked: boolean; onChange: (v: boolean) => void }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      onClick={() => onChange(!checked)}
      className={`w-11 h-6 flex items-center rounded-full p-1 transition-colors ${checked ? 'bg-[#4f46e5]' : 'bg-slate-300'}`}
    >
      <div className={`bg-white w-4 h-4 rounded-full shadow-md transform transition-transform ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
    </button>
  );
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET() {
  const user = await prisma.user.findFirst();
  return NextResponse.json(user);
}

export async function PUT(req: Request) {
  const body = await req.json();
  const updated = await prisma.user.update({
    where: { email: body.email },
    data: { fullName: body.fullName, emailDueDates: body.emailDueDates, weeklySprint: body.weeklySprint },
  });
  return NextResponse.json(updated);
}
